"""Render a local research plan; scenarios are proposals, not test results."""
from pathlib import Path
import html,json
ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'outputs'
plan=json.loads((OUT/'OpenAEC-UI-taakproeven.json').read_text())
e=lambda x:html.escape(str(x))
ul=lambda xs:'<ul>'+''.join('<li>'+e(x)+'</li>' for x in xs)+'</ul>'
css='''*{box-sizing:border-box}body{margin:0;background:#f1eeea;color:#2a2a32;font:17px/1.65 system-ui,sans-serif}header,main,footer{max-width:1050px;margin:auto;padding:32px}header{background:#2a2a32;color:#f1eeea}header a{color:#fbbf24}section{background:#fff;padding:28px;margin:24px 0;border-radius:10px}h1{font-size:clamp(2rem,5vw,3rem);line-height:1.15}h2{font-size:1.5rem;line-height:1.3}h3{font-size:1.1rem;margin-top:1.6rem}p,li{max-width:82ch}a{color:#92400e;text-underline-offset:3px}a:focus-visible{outline:3px solid #b45309;outline-offset:3px}.notice{border-left:4px solid #b45309;padding-left:16px}.meta{font-size:.9rem;color:#5f5f65}.eyebrow{font-size:.85rem;text-transform:uppercase;letter-spacing:.06em}@media(max-width:650px){header,main,footer{padding:18px}section{padding:20px}}@media print{body{background:#fff}header{background:#fff;color:#222}header a{color:#222}section{border:1px solid #aaa}h2,h3{break-after:avoid}}'''
doc='<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpenAEC — voorgestelde taakproeven</title><style>'+css+'</style></head><body><header><div class="eyebrow">Concept voor gezamenlijk plan</div><h1>Van ontwerponderzoek naar bewijs in echte taken</h1><p>Zes voorgestelde proefopzetten voor de eerste harmonisatiefase.</p><p><a href="OpenAEC-UI-ochtendoverzicht.html">Ochtendoverzicht</a> · <a href="OpenAEC-UI-verdiepingsonderzoek.html#module-14">Onderzoek en validatiestrategie</a></p></header><main>'
doc+='<section id="status"><h2>Status en keuzes vooraf</h2><p class="notice"><strong>'+e(plan['status'])+'</strong></p><p>'+e(plan['scope'])+'</p>'+ul(plan['decision_inputs'])+'<p>Deze opzet concretiseert bestaande voorstellen. De eerste scope en acceptatiecriteria worden samen gekozen. De eerdere uitgevoerde, geïsoleerde proeven staan in <a href="OpenAEC-UI-proeven.json">het afzonderlijke bewijsregister</a>.</p><nav aria-label="Taakproeven"><ol>'+''.join('<li><a href="#'+e(f['id'])+'">'+e(f['id']+' · '+f['title'])+'</a></li>' for f in plan['fixtures'])+'</ol></nav></section>'
for f in plan['fixtures']:
    doc+='<section id="'+e(f['id'])+'"><div class="eyebrow">'+e(f['id']+' · '+f['group'])+'</div><h2>'+e(f['title'])+'</h2><p class="meta">'+e(f['status'])+'</p><h3>Fixture en uitgangspunt</h3><p>'+e(f['given'])+'</p><h3>Uit te voeren</h3>'+ul(f['actions'])+'<h3>Vooraf af te spreken uitkomst</h3>'+ul(f['expected'])+'<h3>Te bewaren bewijs</h3>'+ul(f['evidence'])+'<p>Bevindingen: '+e(', '.join(f['finding_ids']))+'. Bronplaatsen: '+', '.join('<a href="OpenAEC-UI-verdiepingsonderzoek.html#source-'+e(id)+'">'+e(id)+'</a>' for id in f['source_ids'])+'.</p></section>'
    if f.get('text_fixture_examples'):
        examples='<ul style="overflow-wrap:anywhere">'+''.join('<li><bdi dir="auto">'+e(x)+'</bdi></li>' for x in f['text_fixture_examples'])+'</ul>'
        doc+='<section id="'+e(f['id'])+'-tekst"><h2>Voorgestelde lange en gemengde tekst voor '+e(f['id'])+'</h2><p>Fictieve tekstgevallen; deze namen verwijzen niet naar echte projectbestanden. Een rendererproef is nog niet uitgevoerd.</p>'+examples+'</section>'
doc+='<section id="omgeving"><h2>Omgeving en rapportage</h2><p>Kies passende combinaties voor de beloofde productscope; dit is geen opdracht om elke mogelijke combinatie tegelijk te testen.</p>'+ul(plan['environment_axes'])+'<h3>Minimaal vastleggen</h3>'+ul(plan['report_fields'])+'<p>Een niet-uitgevoerde platformproef blijft zichtbaar als <em>not-run</em>. Een mislukte proef wordt niet vervangen door een geslaagde kleinere proef met een andere claim.</p></section><section><h2>Grenzen</h2>'+ul(plan['limits'])+'<p><a href="OpenAEC-UI-taakproeven.json">Machineleesbare proefopzet</a> · <a href="OpenAEC-UI-componentcontracten.json">Bestaand gedrag en hostgrenzen</a> · <a href="OpenAEC-UI-versieaudit.json">Bronversies</a></p></section></main><footer><p>Lokale onderzoeksbijlage, bijgewerkt '+e(plan['updated_at'])+'. Geen productie- of ontwerpbesluit namens de gebruiker genomen.</p></footer></body></html>'
(OUT/'OpenAEC-UI-taakproeven.html').write_text(doc)
print(json.dumps(dict(proposed_fixtures=len(plan['fixtures']),bytes=len(doc.encode()))))
